const form=document.getElementById('booking'),arrival=document.getElementById('checkin'),departure=document.getElementById('checkout'),guests=document.getElementById('guests'),select=document.getElementById('cabin-choice'),result=document.getElementById('booking-result');const cabins={Aurora:{rate:390,max:2},Neblina:{rate:520,max:4},Horizonte:{rate:590,max:2}};const localDate=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;arrival.min=localDate(new Date());arrival.addEventListener('change',()=>{if(!arrival.value)return;const d=new Date(arrival.value+'T12:00:00');d.setDate(d.getDate()+1);departure.min=localDate(d);if(departure.value<=arrival.value)departure.value='';result.textContent=''});function cabinChanged(){const c=cabins[select.value];if(c&&Number(guests.value)>c.max){guests.value=String(c.max);result.textContent=`A cabana ${select.value} recebe até ${c.max} pessoas. Ajustamos o número de hóspedes.`}else result.textContent=''}select.addEventListener('change',cabinChanged);guests.addEventListener('change',cabinChanged);form.addEventListener('submit',e=>{e.preventDefault();const nights=(Date.parse(departure.value+'T12:00:00Z')-Date.parse(arrival.value+'T12:00:00Z'))/86400000;if(!(nights>0&&nights<=30)){result.textContent='Escolha uma saída após a chegada, com até 30 noites.';return}const name=select.value==='auto'?(Number(guests.value)>2?'Neblina':'Aurora'):select.value;const price=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(nights*cabins[name].rate);result.textContent=`Sua pausa: ${nights} ${nights===1?'noite':'noites'} na cabana ${name}, para ${guests.value} ${guests.value==='1'?'pessoa':'pessoas'}. Total ilustrativo: ${price}. Esta simulação não consulta disponibilidade nem realiza reserva.`});document.querySelectorAll('[data-cabin]').forEach(b=>b.addEventListener('click',()=>{select.value=b.dataset.cabin;cabinChanged();result.textContent='Cabana '+select.value+' selecionada. Escolha as datas da sua pausa.';document.getElementById('reserva').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});arrival.focus({preventScroll:true})}));const days={morning:['☀','MANHÃ / SEM ALARME','O café é seu único horário.','A luz entra aos poucos. O café passa. O pão chega à mesa. Comece o dia sem a urgência de estar em outro lugar.'],afternoon:['↟','TARDE / SEM ROTEIRO','O caminho também é o destino.','Uma trilha leve, uma pausa na sombra, uma conversa no deck. Você escolhe o ritmo — inclusive o de não fazer nada.'],night:['☾','NOITE / SEM TELAS','Tem um céu inteiro lá fora.','O dia diminui o volume. Prepare algo gostoso, puxe uma cadeira e deixe a noite acontecer sem uma programação.']};const tabs=[...document.querySelectorAll('[data-day]')];function setDay(b){tabs.forEach(x=>{x.setAttribute('aria-selected',String(x===b));x.tabIndex=x===b?0:-1});const d=days[b.dataset.day];['day-icon','day-label','day-title','day-copy'].forEach((id,i)=>document.getElementById(id).textContent=d[i]);document.getElementById('day-panel').setAttribute('aria-labelledby',b.id)}tabs.forEach((b,i)=>{b.addEventListener('click',()=>setDay(b));b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const t=tabs[(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];setDay(t);t.focus()}})});setDay(tabs[0]);